// Utility Functions

/**
 * Generate a unique ID
 */
function generateId(prefix = 'id') {
    return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Sanitize string for use as ID
 */
function sanitizeId(str) {
    return str.toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
}

/**
 * Generate thumbnail from image file
 */
async function generateThumbnail(file, maxWidth = 200, maxHeight = 150) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        
        reader.onload = (e) => {
            const img = new Image();
            
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d');
                
                let width = img.width;
                let height = img.height;
                
                if (width > height) {
                    if (width > maxWidth) {
                        height *= maxWidth / width;
                        width = maxWidth;
                    }
                } else {
                    if (height > maxHeight) {
                        width *= maxHeight / height;
                        height = maxHeight;
                    }
                }
                
                canvas.width = width;
                canvas.height = height;
                ctx.drawImage(img, 0, 0, width, height);
                
                resolve(canvas.toDataURL('image/jpeg', 0.7));
            };
            
            img.onerror = reject;
            img.src = e.target.result;
        };
        
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/**
 * Load image file as data URL, with optional downscaling and compression.
 * @param {File|Blob} file
 * @param {Object} [options]
 * @param {number} [options.maxDimension] - Max width/height; if exceeded, image is downscaled proportionally
 * @param {number} [options.quality=0.85] - Output image quality (for JPEG/WebP)
 * @param {string} [options.format] - Explicit output format ('image/jpeg', 'image/png', 'image/webp')
 * @returns {Promise<string>}
 */
async function loadImageAsDataUrl(file, options = {}) {
    const { maxDimension, quality = 0.85, format = null } = options;
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const rawDataUrl = e.target.result;
            if (!maxDimension) {
                return resolve(rawDataUrl);
            }

            const img = new Image();
            img.onload = () => {
                let { width, height } = img;
                if (width <= maxDimension && height <= maxDimension && !format && file.size < 500 * 1024) {
                    return resolve(rawDataUrl);
                }

                if (width > maxDimension || height > maxDimension) {
                    if (width > height) {
                        height = Math.round((height * maxDimension) / width);
                        width = maxDimension;
                    } else {
                        width = Math.round((width * maxDimension) / height);
                        height = maxDimension;
                    }
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return resolve(rawDataUrl);
                }
                ctx.drawImage(img, 0, 0, width, height);

                const outFormat = format || (file.type === 'image/png' ? 'image/png' : 'image/jpeg');
                const outQuality = outFormat === 'image/png' ? undefined : quality;
                try {
                    resolve(canvas.toDataURL(outFormat, outQuality));
                } catch (err) {
                    resolve(rawDataUrl);
                }
            };
            img.onerror = () => resolve(rawDataUrl);
            img.src = rawDataUrl;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/**
 * Show toast notification (no-op when no toast element exists)
 */
function showToast(message, type = 'info', duration = 3000) {
    const toast = document.getElementById('toast');
    if (!toast) {
        return;
    }
    toast.textContent = message;
    toast.className = `toast ${type}`;
    toast.classList.add('show');
    
    setTimeout(() => {
        toast.classList.remove('show');
    }, duration);
}

/**
 * Escape a string for safe interpolation into an HTML text/attribute context
 */
function escapeHtml(str) {
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

/**
 * Serialize JSON for safe embedding inside a <script> block.
 * Neutralizes </script> breakouts and HTML delimiters by escaping
 * <, >, &, U+2028 and U+2029 in the serialized output.
 */
function safeJsonStringify(data, indent) {
    return JSON.stringify(data, null, indent)
        .replace(/</g, '\\u003c')
        .replace(/>/g, '\\u003e')
        .replace(/\u2028/g, '\\u2028')
        .replace(/\u2029/g, '\\u2029');
}

/**
 * Show modal
 */
function showModal(modalId) {
    const modal = document.getElementById(modalId);
    if (modal) {
        modal.classList.add('show');
    }
}

/**
 * Hide modal
 */
function hideModal(modalId) {
    const modal = document.getElementById(modalId);
    if (modal) {
        modal.classList.remove('show');
    }
}

/**
 * Format file size
 */
function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
}

/**
 * Download text as file
 */
function downloadTextAsFile(text, filename) {
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

/**
 * Copy text to clipboard
 */
async function copyToClipboard(text) {
    try {
        await navigator.clipboard.writeText(text);
        return true;
    } catch (err) {
        // Fallback for older browsers
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.select();
        const success = document.execCommand('copy');
        document.body.removeChild(textarea);
        return success;
    }
}

/**
 * Debounce function
 */
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

/**
 * Convert position object to string
 */
function positionToString(pos) {
    return `${pos.x.toFixed(1)} ${pos.y.toFixed(1)} ${pos.z.toFixed(1)}`;
}

/**
 * Parse position string to object
 */
function parsePosition(str) {
    const parts = str.split(' ').map(Number);
    return { x: parts[0] || 0, y: parts[1] || 0, z: parts[2] || 0 };
}

/**
 * Validate email
 */
function isValidEmail(email) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
}

/**
 * Deep clone object
 */
function deepClone(obj) {
    return JSON.parse(JSON.stringify(obj));
}

export {
    generateId,
    sanitizeId,
    generateThumbnail,
    loadImageAsDataUrl,
    showToast,
    showModal,
    hideModal,
    formatFileSize,
    downloadTextAsFile,
    copyToClipboard,
    debounce,
    positionToString,
    parsePosition,
    isValidEmail,
    deepClone,
    escapeHtml,
    safeJsonStringify
};
